/**
 * Decryption Pipeline for ChaCha20-Poly1305
*/
#include "arrays.h"
// Top level IO port config, named like chacha20poly1305_decrypt_*
#include "chacha20poly1305/chacha20poly1305_decrypt.h"
// Instance of chacha20 part of decryption
#define CHACHA_INST chacha20_decrypt
#include "chacha20/chacha20.c"
// Instance of preparing auth data part of decryption
#define PREP_AUTH_DATA_INST prep_auth_data_decrypt
#include "prep_auth_data/prep_auth_data.c"
// Instance of poly1305 part of decryption
#define POLY_MAC_INST poly1305_mac_decrypt
#include "poly1305/poly1305_mac.c"
// Instance of the poly1305 verification block
#include "poly1305/poly1305_verify_decrypt.c"
// Instance of strip auth tag
#include "auth_tag/strip_auth_tag.c"
// Instance wait to verify block 
#include "auth_tag/wait_to_verify.c"


// The primary dataflow for single clock domain ChaCha20-Poly1305 decryption
#pragma PART "xc7a200tffg1156-2" // Artix 7 200T
#include "chacha20poly1305/decrypt_dataflow.c"

// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

// Instance of chacha20_loop_body
// requires data width converters to-from 512b wide blocks 128b bus
// use axis128/512 stream types
#include "axi/axis.h"
#include "global_func_inst.h"
#include "chacha20.h"
#include "../poly1305/poly1305.h"

#ifndef CHACHA_INST
#define CHACHA_INST chacha20
#endif

// Globally visible ports
// CSR inputs
uint8_t PPCAT(CHACHA_INST,_key)[CHACHA20_KEY_SIZE]; // input
uint8_t PPCAT(CHACHA_INST,_nonce)[CHACHA20_NONCE_SIZE]; // input
// Input plaintext
stream(axis128_t) PPCAT(CHACHA_INST,_axis_in); // input
uint1_t PPCAT(CHACHA_INST,_axis_in_ready); // output
// Output poly1305_key
stream(poly1305_key_uint_t) PPCAT(CHACHA_INST,_poly_key); // output
uint1_t PPCAT(CHACHA_INST,_poly_key_ready); // input
// Output ciphertext
stream(axis128_t) PPCAT(CHACHA_INST,_axis_out); // output
uint1_t PPCAT(CHACHA_INST,_axis_out_ready); // input

#ifndef CHACHA_EXCLUDES_PIPELINE
// Global instance of the chacha20_loop_body pipeline
GLOBAL_VALID_READY_PIPELINE_INST(PPCAT(CHACHA_INST,_pipeline), axis512_t, chacha20_loop_body, chacha20_loop_body_in_t, 64)
#endif

// Instance of FSM to control pipeline
MAIN(CHACHA_INST)
void CHACHA_INST(){
  chacha20_fsm_t fsm_out = chacha20_fsm(
    PPCAT(CHACHA_INST,_key),
    PPCAT(CHACHA_INST,_nonce),
    PPCAT(CHACHA_INST,_axis_in),
    PPCAT(CHACHA_INST,_poly_key_ready),
    PPCAT(CHACHA_INST,_axis_out_ready),
    PPCAT(CHACHA_INST,_pipeline_in_ready),
    PPCAT(CHACHA_INST,_pipeline_out)
  );
  PPCAT(CHACHA_INST,_axis_in_ready) = fsm_out.ready_for_axis_in;
  PPCAT(CHACHA_INST,_poly_key) = fsm_out.poly_key;
  PPCAT(CHACHA_INST,_axis_out) = fsm_out.axis;
  PPCAT(CHACHA_INST,_pipeline_in) = fsm_out.to_pipeline;
  PPCAT(CHACHA_INST,_pipeline_out_ready) = fsm_out.ready_for_from_pipeline;
}

#undef CHACHA_INST

// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

// The primary dataflow for single clock domain ChaCha20-Poly1305 decryption
#pragma MAIN_MHZ decrypt_dataflow 80.0
void decrypt_dataflow(){

    // Strip auth tag (splits input streams)
    // Connect chacha20poly1305_decrypt_* input stream to strip_auth_tag
    strip_auth_tag_axis_in = chacha20poly1305_decrypt_axis_in;
    chacha20poly1305_decrypt_axis_in_ready = strip_auth_tag_axis_in_ready;

