212	axis512_t chacha20_loop_body(
213	  chacha20_loop_body_in_t inputs
214	){
215	  uint8_t in_data[CHACHA20_BLOCK_SIZE] = inputs.axis_in.tdata; // TODO handle tkeep
216	  uint8_t key[CHACHA20_KEY_SIZE] = inputs.key;
217	  uint8_t nonce[CHACHA20_NONCE_SIZE] = inputs.nonce;
218	  uint32_t counter = inputs.counter;
219	
220	  chacha20_state state = chacha20_init(key, nonce, counter);
221	  chacha20_state block = chacha20_block(state);
222	
223	  // PipelineC byte casting funcs
224	  chacha20_state_bytes_t block_bytes_t = chacha20_state_to_bytes(block);
225	  uint8_t block_bytes[CHACHA20_BLOCK_SIZE] = block_bytes_t.data;
226	
227	  uint8_t out_data[CHACHA20_BLOCK_SIZE];
228	  // TODO partial in data, i.e. partial tkeep
229	  //    size_t chunk_size = length > 64 ? 64 : length;
230	  for(uint32_t i = 0; i < CHACHA20_BLOCK_SIZE; i+=1)
231	  {
232	    out_data[i] = in_data[i] ^ block_bytes[i];
233	  }
234	  // Output pass though AXIS tlast,tkeep,tvalid
235	  axis512_t axis_out = inputs.axis_in;
236	  // Data bytes are encrypted output of chacha20
237	  axis_out.tdata = out_data;
238	  return axis_out;
